                    c_data[i] = a_data[i % a_data.len] / b_val;
                }
            },
            else => return error.UnsupportedType,
        }
        return result;
    }

    pub fn matmul(self: *Tensor, other: *Tensor) !*Tensor {
        if (self.dtype != other.dtype) return error.TypeMismatch;
        if (self.shape.dims.len != 2 or other.shape.dims.len != 2) return error.InvalidShape;
        if (self.shape.dims[1] != other.shape.dims[0]) return error.DimensionMismatch;
        var result_shape = try TensorShape.init(self.allocator, &.{ self.shape.dims[0], other.shape.dims[1] });
        errdefer result_shape.deinit();
        var result = try init(self.allocator, result_shape.dims, self.dtype);
        errdefer result.deinit();
        const m = self.shape.dims[0];
        const k = self.shape.dims[1];
        const n = other.shape.dims[1];
        switch (self.dtype) {
            .f32 => {
                const a = self.data.f32;
                const b = other.data.f32;
                const c_data = result.data.f32;
                var i: usize = 0;
                while (i < m) : (i += 1) {
                    var j: usize = 0;
                    while (j < n) : (j += 1) {
                        var sum: f32 = 0.0;
                        var l: usize = 0;
                        while (l < k) : (l += 1) {
                            sum += a[i * k + l] * b[l * n + j];
                        }
                        c_data[i * n + j] = sum;
                    }
                }
            },
            .f64 => {
                const a = self.data.f64;
                const b = other.data.f64;
                const c_data = result.data.f64;
                var i: usize = 0;
                while (i < m) : (i += 1) {
                    var j: usize = 0;
                    while (j < n) : (j += 1) {
                        var sum: f64 = 0.0;
                        var l: usize = 0;
                        while (l < k) : (l += 1) {
                            sum += a[i * k + l] * b[l * n + j];
                        }
                        c_data[i * n + j] = sum;
                    }
                }
            },
            else => return error.UnsupportedType,
        }
        return result;
    }

    pub fn transpose(self: *Tensor) !*Tensor {
        if (self.shape.dims.len != 2) return error.InvalidShape;
        var new_dims = &.{ self.shape.dims[1], self.shape.dims[0] };
        var result = try init(self.allocator, new_dims, self.dtype);
        errdefer result.deinit();
        const rows = self.shape.dims[0];
        const cols = self.shape.dims[1];
        switch (self.dtype) {
            .f32 => {
                const src = self.data.f32;
                const dst = result.data.f32;
                var i: usize = 0;
                while (i < rows) : (i += 1) {
                    var j: usize = 0;
                    while (j < cols) : (j += 1) {
                        dst[j * rows + i] = src[i * cols + j];
                    }
                }
            },
            .f64 => {
                const src = self.data.f64;
                const dst = result.data.f64;
                var i: usize = 0;
                while (i < rows) : (i += 1) {
                    var j: usize = 0;
                    while (j < cols) : (j += 1) {
                        dst[j * rows + i] = src[i * cols + j];
                    }
                }
            },
            else => return error.UnsupportedType,
        }
        return result;
    }

    pub fn relu(self: *Tensor) !*Tensor {
        var result = try self.copy();
        errdefer result.deinit();
        switch (self.dtype) {
            .f32 => {
                for (result.data.f32) |*val| {
                    if (val.* < 0) val.* = 0;
                }
            },
            .f64 => {
                for (result.data.f64) |*val| {
                    if (val.* < 0) val.* = 0;
                }
            },
            else => return error.UnsupportedType,
        }
        return result;
    }

    pub fn sigmoid(self: *Tensor) !*Tensor {
        var result = try self.copy();
        errdefer result.deinit();
        switch (self.dtype) {
            .f32 => {
                for (result.data.f32) |*val| {
                    val.* = 1.0 / (1.0 + @exp(-val.*));
                }
            },
            .f64 => {
                for (result.data.f64) |*val| {
                    val.* = 1.0 / (1.0 + @exp(-val.*));
                }
            },
            else => return error.UnsupportedType,
        }
        return result;
    }

    pub fn softmax(self: *Tensor, dim: usize) !*Tensor {
        if (dim >= self.shape.dims.len) return error.InvalidDimension;
        var result = try self.copy();
        errdefer result.deinit();
        const axis_size = self.shape.dims[dim];
        const outer_size = blk: {
            var s: usize = 1;
            var i: usize = 0;
            while (i < dim) : (i += 1) s *= self.shape.dims[i];
            break :blk s;
        };
        const inner_size = blk: {
            var s: usize = 1;
            var i = dim + 1;
            while (i < self.shape.dims.len) : (i += 1) s *= self.shape.dims[i];
            break :blk s;
        };
        switch (self.dtype) {
            .f64 => {
                const data = result.data.f64;
                var outer: usize = 0;
                while (outer < outer_size) : (outer += 1) {
                    var inner: usize = 0;
                    while (inner < inner_size) : (inner += 1) {
                        var max_val: f64 = -math.floatMax(f64);
                        var i: usize = 0;
                        while (i < axis_size) : (i += 1) {
                            const idx = outer * axis_size * inner_size + i * inner_size + inner;
                            max_val = @max(max_val, data[idx]);
                        }
                        var sum: f64 = 0.0;
                        i = 0;
                        while (i < axis_size) : (i += 1) {
                            const idx = outer * axis_size * inner_size + i * inner_size + inner;
                            data[idx] = @exp(data[idx] - max_val);
                            sum += data[idx];
                        }
                        i = 0;
                        while (i < axis_size) : (i += 1) {
                            const idx = outer * axis_size * inner_size + i * inner_size + inner;
                            data[idx] /= sum;
                        }
                    }
                }
            },
            else => return error.UnsupportedType,
        }
        return result;
    }

    pub fn argmax(self: *Tensor, dim: usize) !*Tensor {
        if (dim >= self.shape.dims.len) return error.InvalidDimension;
        var new_dims = try self.allocator.alloc(usize, self.shape.dims.len - 1);
        errdefer self.allocator.free(new_dims);
        var j: usize = 0;
        var i: usize = 0;
        while (i < self.shape.dims.len) : (i += 1) {
            if (i != dim) {
                new_dims[j] = self.shape.dims[i];
                j += 1;
            }
        }
        var result = try init(self.allocator, new_dims, .u32);
        self.allocator.free(new_dims);
        errdefer result.deinit();
        const axis_size = self.shape.dims[dim];
        const outer_size = blk: {
            var s: usize = 1;
            i = 0;
            while (i < dim) : (i += 1) s *= self.shape.dims[i];
            break :blk s;
        };
        const inner_size = blk: {
            var s: usize = 1;
            i = dim + 1;
            while (i < self.shape.dims.len) : (i += 1) s *= self.shape.dims[i];
            break :blk s;
        };
        switch (self.dtype) {
            .f64 => {
                const data = self.data.f64;
                const indices = result.data.u32;
                var outer: usize = 0;
                while (outer < outer_size) : (outer += 1) {
                    var inner: usize = 0;
                    while (inner < inner_size) : (inner += 1) {
                        var max_val: f64 = -math.floatMax(f64);
                        var max_idx: u32 = 0;
                        i = 0;
                        while (i < axis_size) : (i += 1) {
                            const idx = outer * axis_size * inner_size + i * inner_size + inner;
                            if (data[idx] > max_val) {
                                max_val = data[idx];
                                max_idx = @intCast(i);
                            }
                        }
                        const res_idx = outer * inner_size + inner;
                        indices[res_idx] = max_idx;
                    }
                }
            },
            else => return error.UnsupportedType,
        }
        return result;
    }

    pub fn sum(self: *Tensor, dim: ?usize) !*Tensor {
        const reduce_all = dim == null;
        const reduce_dim = dim orelse 0;
        if (!reduce_all and reduce_dim >= self.shape.dims.len) return error.InvalidDimension;
        var new_dims: []usize = undefined;
        if (reduce_all) {
            new_dims = try self.allocator.alloc(usize, 1);
            new_dims[0] = 1;
        } else {
            new_dims = try self.allocator.alloc(usize, self.shape.dims.len - 1);
            errdefer self.allocator.free(new_dims);
            var j: usize = 0;
            var i: usize = 0;
            while (i < self.shape.dims.len) : (i += 1) {
                if (i != reduce_dim) {
                    new_dims[j] = self.shape.dims[i];
                    j += 1;
                }
            }
        }
        defer self.allocator.free(new_dims);
        var result = try zeros(self.allocator, new_dims, self.dtype);
        errdefer result.deinit();
        switch (self.dtype) {
            .f32 => {
                const src = self.data.f32;
                const dst = result.data.f32;
                if (reduce_all) {
                    var s: f32 = 0.0;
                    for (src) |val| s += val;
                    dst[0] = s;
                } else {
                    const axis_size = self.shape.dims[reduce_dim];
                    const outer_size = blk: {
                        var s: usize = 1;
                        var i: usize = 0;
                        while (i < reduce_dim) : (i += 1) s *= self.shape.dims[i];
                        break :blk s;
                    };
                    const inner_size = blk: {
                        var s: usize = 1;
                        var i = reduce_dim + 1;
                        while (i < self.shape.dims.len) : (i += 1) s *= self.shape.dims[i];
                        break :blk s;
                    };
                    var outer: usize = 0;
                    while (outer < outer_size) : (outer += 1) {
                        var inner: usize = 0;
                        while (inner < inner_size) : (inner += 1) {
                            var sum_val: f32 = 0.0;
                            var k: usize = 0;
                            while (k < axis_size) : (k += 1) {
                                const idx = outer * axis_size * inner_size + k * inner_size + inner;
                                sum_val += src[idx];
                            }
                            const res_idx = outer * inner_size + inner;
                            dst[res_idx] = sum_val;
                        }
                    }
                }
            },
            .f64 => {
                const src = self.data.f64;
                const dst = result.data.f64;
                if (reduce_all) {
                    var s: f64 = 0.0;
                    for (src) |val| s += val;
                    dst[0] = s;
                } else {
                    const axis_size = self.shape.dims[reduce_dim];
                    const outer_size = blk: {
                        var s: usize = 1;
                        var i: usize = 0;
                        while (i < reduce_dim) : (i += 1) s *= self.shape.dims[i];
                        break :blk s;
                    };
                    const inner_size = blk: {
                        var s: usize = 1;
                        var i = reduce_dim + 1;
                        while (i < self.shape.dims.len) : (i += 1) s *= self.shape.dims[i];
                        break :blk s;
                    };
                    var outer: usize = 0;
                    while (outer < outer_size) : (outer += 1) {
                        var inner: usize = 0;
                        while (inner < inner_size) : (inner += 1) {
                            var sum_val: f64 = 0.0;
                            var k: usize = 0;
                            while (k < axis_size) : (k += 1) {
                                const idx = outer * axis_size * inner_size + k * inner_size + inner;
                                sum_val += src[idx];
                            }
                            const res_idx = outer * inner_size + inner;
                            dst[res_idx] = sum_val;
                        }
                    }
                }
            },
            else => return error.UnsupportedType,
        }
        return result;
    }

    pub fn mean(self: *Tensor, dim: ?usize) !*Tensor {
        var sum_tensor = try self.sum(dim);
        errdefer sum_tensor.deinit();
        const divisor: f64 = if (dim) |d| @floatFromInt(self.shape.dims[d]) else @floatFromInt(self.shape.total_elements());
        switch (sum_tensor.dtype) {
            .f64 => {
                for (sum_tensor.data.f64) |*val| val.* /= divisor;
            },
            .f32 => {
                for (sum_tensor.data.f32) |*val| val.* /= @as(f32, @floatCast(divisor));
            },
            else => {},
        }
        return sum_tensor;
    }

    pub fn variance(self: *Tensor, dim: ?usize) !*Tensor {
        var mean_tensor = try self.mean(dim);
        defer mean_tensor.deinit();
        var diff = try self.sub(mean_tensor);
        defer diff.deinit();
        var sq = try diff.mul(diff);
        defer sq.deinit();
        return try sq.mean(dim);
    }

    pub fn stddev(self: *Tensor, dim: ?usize) !*Tensor {
        var var_tensor = try self.variance(dim);
        errdefer var_tensor.deinit();
        switch (var_tensor.dtype) {
            .f64 => {
                for (var_tensor.data.f64) |*val| val.* = @sqrt(val.*);
            },
            .f32 => {
                for (var_tensor.data.f32) |*val| val.* = @sqrt(val.*);
            },
            else => {},
        }
        return var_tensor;
    }

    pub fn normalize(self: *Tensor, dim: ?usize) !*Tensor {
        var mean_t = try self.mean(dim);
        defer mean_t.deinit();
        var std_t = try self.stddev(dim);
        defer std_t.deinit();
        var centered = try self.sub(mean_t);
        defer centered.deinit();
        return try centered.div(std_t);
    }

    pub fn backward(self: *Tensor) !void {
        if (!self.requires_grad) return;
        if (self.grad == null) {
            self.grad = try ones(self.allocator, self.shape.dims, self.dtype);
        }
    }

    pub fn mulScalar(self: *Tensor, scalar: f64) !*Tensor {
        var result = try self.copy();
        errdefer result.deinit();
        switch (self.dtype) {
            .f64 => {
                for (result.data.f64) |*val| val.* *= scalar;
            },
            .f32 => {
                for (result.data.f32) |*val| val.* *= @as(f32, @floatCast(scalar));
            },
            else => return error.UnsupportedType,
        }
        return result;
    }

    pub fn norm(self: *Tensor, p: f64) !*Tensor {
        if (p != 2.0) return error.UnsupportedNorm;
        var sq = try self.mul(self);
        defer sq.deinit();
        var sum_sq = try sq.sum(null);
        errdefer sum_sq.deinit();
        switch (sum_sq.dtype) {
            .f64 => sum_sq.data.f64[0] = @sqrt(sum_sq.data.f64[0]),
            .f32 => sum_sq.data.f32[0] = @sqrt(sum_sq.data.f32[0]),
            else => return error.UnsupportedType,
        }
        return sum_sq;
    }
};

pub const ModelHeader = struct {
    version: u32,
    num_layers: u32,
    hidden_size: u32,
    vocab_size: u32,
    max_seq_len: u32,
    checksum: u64,
};

pub fn saveModel(allocator: Allocator, path: []const u8, tensors: StringHashMap(*Tensor)) !void {
    var file = try fs.cwd().createFile(path, .{});
    defer file.close();
    var writer = file.writer();
    var header = ModelHeader{ .version = 425, .num_layers = 0, .hidden_size = 0, .vocab_size = 0, .max_seq_len = 0, .checksum = 0 };
    try writer.writeStruct(header);
    const num_tensors: u32 = @intCast(tensors.count());
    try writer.writeInt(u32, num_tensors, .little);
    var it = tensors.iterator();
    var total_size: u64 = 0;
    while (it.next()) |entry| {
        const name = entry.key_ptr.*;
        const tensor = entry.value_ptr.*;
        try writer.writeInt(u32, @intCast(name.len), .little);
        try writer.writeAll(name);
        try writer.writeInt(u32, @intCast(tensor.shape.dims.len), .little);
        for (tensor.shape.dims) |dim| {
            try writer.writeInt(u64, dim, .little);
        }
        try writer.writeInt(u32, @intFromEnum(tensor.dtype), .little);
        const data_size = tensor.shape.total_elements() * tensor.data.elementSize();
        try writer.writeInt(u64, data_size, .little);
        switch (tensor.dtype) {
            .f32 => try writer.writeAll(mem.sliceAsBytes(tensor.data.f32)),
            .f64 => try writer.writeAll(mem.sliceAsBytes(tensor.data.f64)),
            .i32 => try writer.writeAll(mem.sliceAsBytes(tensor.data.i32)),
            .u32 => try writer.writeAll(mem.sliceAsBytes(tensor.data.u32)),
            .c64 => try writer.writeAll(mem.sliceAsBytes(tensor.data.c64)),
            .bool => try writer.writeAll(mem.sliceAsBytes(tensor.data.bool)),
        }
        total_size += data_size;
    }
    const pos = try file.getPos();
    try file.seekTo(0);
    header.checksum = computeChecksum(total_size);
    try writer.writeStruct(header);
    try file.seekTo(pos);
}

fn computeChecksum(size: u64) u64 {
    return size *% 42;
}

pub fn loadModel(allocator: Allocator, path: []const u8) !StringHashMap(*Tensor) {
    var file = try fs.cwd().openFile(path, .{});
    defer file.close();
    var reader = file.reader();
    var header: ModelHeader = try reader.readStruct(ModelHeader);
    if (header.version != 425) return error.InvalidVersion;
    const num_tensors = try reader.readInt(u32, .little);
    var tensors = StringHashMap(*Tensor).init(allocator);
    errdefer {
        var it = tensors.iterator();
        while (it.next()) |entry| {
            entry.value_ptr.*.deinit();
            allocator.free(entry.key_ptr.*);
        }
        tensors.deinit();
    }
    var i: u32 = 0;
    while (i < num_tensors) : (i += 1) {
        const name_len = try reader.readInt(u32, .little);
        var name_buf = try allocator.alloc(u8, name_len);
        _ = try reader.readAll(name_buf);
        const dims_len = try reader.readInt(u32, .little);
        var dims = try allocator.alloc(usize, dims_len);
        var j: u32 = 0;
        while (j < dims_len) : (j += 1) {
            dims[j] = try reader.readInt(u64, .little);
        }
        const dtype_int = try reader.readInt(u32, .little);
        const dtype: DataType = @enumFromInt(dtype_int);
        _ = try reader.readInt(u64, .little);
        var tensor = try Tensor.init(allocator, dims, dtype);
        allocator.free(dims);
        switch (dtype) {
            .f32 => _ = try reader.readAll(mem.sliceAsBytes(tensor.data.f32)),
            .f64 => _ = try reader.readAll(mem.sliceAsBytes(tensor.data.f64)),
            .i32 => _ = try reader.readAll(mem.sliceAsBytes(tensor.data.i32)),
            .u32 => _ = try reader.readAll(mem.sliceAsBytes(tensor.data.u32)),
            .c64 => _ = try reader.readAll(mem.sliceAsBytes(tensor.data.c64)),
            .bool => _ = try reader.readAll(mem.sliceAsBytes(tensor.data.bool)),
        }
        try tensors.put(name_buf, tensor);
    }
    return tensors;
}

pub fn saveConfig(allocator: Allocator, path: []const u8, config: anytype) !void {
    var file = try fs.cwd().createFile(path, .{});
    defer file.close();
    var string = try json.stringifyAlloc(allocator, config, .{ .whitespace = .indent_2 });
    defer allocator.free(string);
    try file.writeAll(string);
}

pub fn loadConfig(comptime T: type, allocator: Allocator, path: []const u8) !T {
    var file = try fs.cwd().openFile(path, .{});
    defer file.close();
    var buf = try file.readToEndAlloc(allocator, 1 << 20);
    defer allocator.free(buf);
    var parsed = try json.parseFromSlice(T, allocator, buf, .{});
    defer parsed.deinit();
    return parsed.value;
}

